window.APP_ESSAY_PAPERS["local1-漁場學"] = [{"roc":111,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111190&c=330&s=2806&q=1","qs":[{"n":1,"q":"黑潮流經臺灣東北部海域並形成重要漁場，而黑潮在東北部海域流動呈現季節及年間變化，請說明黑潮主流接近或遠離臺灣東北部陸棚邊緣時，對該海域鯖魚漁場將造成何種影響？（20 分）","pt":20},{"n":2,"q":"我國遠洋鰹鮪圍網漁業發展成熟，但其產業現況面臨氣候變遷考驗，請說明中西太平洋海洋環境變動如何影響鰹鮪魚群分佈？（20 分）","pt":20},{"n":3,"q":"漁況預報有助產業精準掌握魚群中心降低海上搜尋成本，請說明如何進行漁況預報，且預報的原理有那些？（20 分）","pt":20},{"n":4,"q":"康氏馬加鰆（俗稱土魠魚）是臺灣沿近海重要經濟魚種，請詳細說明該魚種之主要漁場區域、漁況及海況特性。（20 分）","pt":20},{"n":5,"q":"臺灣東北部海域及西南海域在颱風過後可以短期影響魚群來游量，請詳細說明颱風過後將如何改變海況與漁況？其動態機制為何？（20 分）","pt":20}]},{"roc":108,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108190&c=351&s=3408&q=1","qs":[{"n":1,"q":"臺灣海峽為我國重要沿近海漁場之一。試說明臺灣海峽冬季水文環境的樣態及可能產生水溫異常的水域為何？（20 分）","pt":20},{"n":2,"q":"食物鏈的能階結構通常是評估漁場形成機制的要素之一。試就所知，分別說明大洋域（Open Sea）、陸棚區（Continental shelves）與湧昇域（Upwelling regions）的食物鏈能階（Trophic levels）結構。（20 分）","pt":20},{"n":3,"q":"遙感探測（Remote Sensing）是調查海洋基礎生產力的方法之一，試說明運用此一方法計算海洋基礎生產力須考慮那些因素？（20 分）","pt":20},{"n":4,"q":"黑潮大蛇行係指黑潮主軸流經日本東側之西北太平洋水域的一種偏移現象，試說明如何研判黑潮大蛇行現象的發生？（5 分）而此一海流大蛇行的變動現象對西北太平洋秋刀魚分布的可能影響為何？（15 分）","pt":20},{"n":5,"q":"海洋生物環境區可以光線的有無區分為有光區、微光區與無光區，其中無光區為海洋空間最大區域，但此一區域也具備高壓、低溶氧、食物不足等惡劣環境條件。試說明無光區空間之生物如何適應此一惡劣的環境條件？（20 分）","pt":20}]},{"roc":107,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107190&c=344&s=3309&q=1","qs":[{"n":1,"q":"何謂海洋溫度躍層（Thermocline）？熱帶太平洋鮪延繩漁場從東太平洋到西太平洋其水溫躍層深度有何變化？試述之。      （20 分）","pt":20},{"n":2,"q":"海洋漁場中營養鹽類有那些？其對漁場生產力有何影響，試述之。（20 分）","pt":20},{"n":3,"q":"（一）漁場基礎生產力（Primary Productivity）之高低與魚群豐度是否存在著直接關係，為什麼？（10 分）\n（二）陽光透過層以下的魚群生產量受到那些因素之影響？（10 分）","pt":20},{"n":4,"q":"我國近海及遠洋漁業利用中的湧升流漁場在那裡？並說明發生原因及其主要漁獲魚種。（20 分）","pt":20},{"n":5,"q":"中深海大洋生活環境區（Mesopelagic Environmental Biozone）之生物，試問何以其背部多呈黑色或暗紅色，腹部呈銀白色？很多棲息中深海之生物具有發光器之目的何在？其具有大的眼睛之原因為何？其在海洋漁場生物生產與生態所扮演之角色為何？（20 分）","pt":20}]},{"roc":106,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106190&c=341&s=2908&q=1","qs":[{"n":1,"q":"何謂漁況預報？漁況預報有幾種？請分別敘述之。（20 分）","pt":20},{"n":2,"q":"針對大洋中鮪魚漁場之形成機構中，海底地形是重要因子之一，試述其原因。（20 分）","pt":20},{"n":3,"q":"因應臺灣沿近海漁業資源枯竭，政府積極在做水產資源復育工作，試問其工作項目有那些？其成效如何？其缺失有那些？（20 分）","pt":20},{"n":4,"q":"當海洋環境受到漏油污染時，試述海面上之礦油在自然條件下之運作模式？對漁業及沿岸生態所造成之影響有那些？（20 分）","pt":20},{"n":5,"q":"海洋牧場是今後沿近海漁業發展之重心，請問應包括那些硬體設備及技術並敘述理由？（20 分）","pt":20}]},{"roc":105,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=105180&c=347&s=2708&q=1","qs":[{"n":1,"q":"風成湧昇海域是海洋基礎生產力最高的區域之一，試述離岸風強弱之改變對湧昇海域漁場環境與漁況變動的影響為何？（20 分）","pt":20},{"n":2,"q":"遙測（remote sensing）技術是漁海況預報與海洋漁業環境監測之利器，試就所知運用遙測觀測海洋漁業環境之原理為何？（20 分）","pt":20},{"n":3,"q":"臺灣東北部及西南部水域為櫻花蝦漁業之主要漁場，試比較說明此二漁場之漁況特性。（20 分）","pt":20},{"n":4,"q":"氣候變遷效應已證實對漁業與魚群分布造成影響，試述那些指標常被用來評估氣候變遷效應與太平洋海域之漁業與魚群分布變動的關連性。（20 分）","pt":20},{"n":5,"q":"漁場是提供人類採捕水產資源的場所，然而漁撈行為和其他人為活動卻可能直接或間接影響漁場生態，進而可能對生態系統的平衡造成衝擊，試解釋漁場最大生產量、生態系與漁業管理政策間之關係為何？（20 分）","pt":20}]},{"roc":104,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=104180&c=349&s=2607&q=1","qs":[{"n":1,"q":"我國秋刀魚年別漁獲量高低起伏變動極大，試說明秋刀魚漁況受到那些海洋環境因子的影響。（20 分）","pt":20},{"n":2,"q":"聖嬰現象已被證實是影響中西太平洋鰹鮪圍網漁況變動的重要因素。試說明如何觀測與證實聖嬰現象。（20 分）","pt":20},{"n":3,"q":"海洋渦流區常出現良好漁場，試說明渦流水域形成良好漁場的原理。（20 分）","pt":20},{"n":4,"q":"漁業生物採樣調查是漁海況預報事業與評估之重要資訊，試說明生物採樣調查計畫須考慮那些因素。（20 分）","pt":20},{"n":5,"q":"氣候變遷對全球漁獲量的可能變動影響為何？（20 分）","pt":20}]},{"roc":103,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=103180&c=351&s=2609&q=1","qs":[{"n":1,"q":"請試述下列名詞之意涵：（每小題 4 分，共 20 分）海況（Oceanic condition）漁況（Fishing condition）溫度躍層（thermocline）地轉流（geostrophic flow）潮間帶（intertidal zone）","pt":20},{"n":2,"q":"太平洋黑鮪（Thunnus orientalis）在北太平洋海域洄游，於不同季節，不同體型，在不同海域形成漁場，被不同類別的漁具漁法所捕撈。請就漁場形成的季節和生活史階段說明在不同海域形成的漁場特性，以及使用何種漁具漁法來捕撈太平洋黑鮪？（20 分）","pt":20},{"n":3,"q":"何謂漁場？（5 分）請就形成漁場的條件，說明漁場可以區分為那些類別及其形成條件為何？（15 分）","pt":20},{"n":4,"q":"大陸棚（continental shelf）占全海洋的 7.6%，是公認的良好漁場，如世界三大漁場（北海漁場、南美東岸外海漁場、白令海漁場）以及中國東海、非洲西岸、北美紐芬蘭外海等著名漁場均位於大陸棚域。請說明大陸棚形成良好漁場的原因。（20 分）","pt":20},{"n":5,"q":"漁業管理常因為漁業所處海域，而有不同的考量。例如配額分配時，有沿岸國和漁業國而有不同比例的利益。因此，以漁業發生所處水域的定義，請說明潮間帶漁場、沿岸漁場、近海漁場、外海漁場、深海漁場和遠洋漁場的區別。（20 分）","pt":20}]},{"roc":102,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=102190&c=349&s=2613&q=1","qs":[{"n":1,"q":"臺灣東北部海域為鯖鰺之主要漁場，試從漁業生物與海洋環境等面向說明其形成良好漁場的原因。（20 分）","pt":20},{"n":2,"q":"表面水溫分布圖是漁海況預報必備之素材，試述其可提供那些有關的漁場資訊？（20 分）","pt":20},{"n":3,"q":"何謂漁場之有光層、微光層與無光層（10 分）？分布其間之海洋生物有何不同（10 分）？","pt":20},{"n":4,"q":"海中營養鹽的供應是漁場生產力高低的重要因素之一，何謂營養鹽（4 分）？試述其在海中之垂直剖面分布特性及其循環供應（16 分）。","pt":20},{"n":5,"q":"近年來全球極端氣候頻發，導致有些漁場之魚類大量死亡，稱為死域（Dead zone），其發生之原因為何？（20 分）","pt":20}]}];
